39	/**
40	 * A class responsible for decoding resources either from cached data or from the original source
41	 * and applying transformations and transcodes.
42	 *
43	 * <p>Note: this class has a natural ordering that is inconsistent with equals.
44	 *
45	 * @param <R> The type of resource that will be transcoded from the decoded and transformed
46	 *     resource.
47	 */
48	class DecodeJob<R>
49	    implements DataFetcherGenerator.FetcherReadyCallback,
50	        Runnable,
51	        Comparable<DecodeJob<?>>,
52	        Poolable {
53	  private static final String TAG = "DecodeJob";
