166	  /**
167	   * Returns true if this job will attempt to decode a resource from the disk cache, and false if it
168	   * will always decode from source.
169	   */
170	  boolean willDecodeFromCache() {
171	    Stage firstStage = getNextStage(Stage.INITIALIZE);
172	    return firstStage == Stage.RESOURCE_CACHE || firstStage == Stage.DATA_CACHE;
173	  }
