246	  // We need to rethrow only CallbackException, but not other types of Throwables.
247	  @SuppressWarnings("PMD.AvoidRethrowingException")
248	  @Override
249	  public void run() {
250	    // This should be much more fine grained, but since Java's thread pool implementation silently
251	    // swallows all otherwise fatal exceptions, this will at least make it obvious to developers
252	    // that something is failing.
253	    GlideTrace.beginSectionFormat("DecodeJob#run(reason=%s, model=%s)", runReason, model);
254	    // Methods in the try statement can invalidate currentFetcher, so set a local variable here to
255	    // ensure that the fetcher is cleaned up either way.
256	    DataFetcher<?> localFetcher = currentFetcher;
257	    try {
258	      if (isCancelled) {
259	        notifyFailed();
260	        return;
261	      }
262	      runWrapped();
263	    } catch (CallbackException e) {
264	      // If a callback not controlled by Glide throws an exception, we should avoid the Glide
265	      // specific debug logic below.
266	      throw e;
267	    } catch (Throwable t) {
268	      // Catch Throwable and not Exception to handle OOMs. Throwables are swallowed by our
269	      // usage of .submit() in GlideExecutor so we're not silently hiding crashes by doing this. We
270	      // are however ensuring that our callbacks are always notified when a load fails. Without this
271	      // notification, uncaught throwables never notify the corresponding callbacks, which can cause
272	      // loads to silently hang forever, a case that's especially bad for users using Futures on
273	      // background threads.
274	      if (Log.isLoggable(TAG, Log.DEBUG)) {
275	        Log.d(
276	            TAG,
277	            "DecodeJob threw unexpectedly" + ", isCancelled: " + isCancelled + ", stage: " + stage,
278	            t);
279	      }
280	      // When we're encoding we've already notified our callback and it isn't safe to do so again.
281	      if (stage != Stage.ENCODE) {
282	        throwables.add(t);
283	        notifyFailed();
284	      }
285	      if (!isCancelled) {
286	        throw t;
287	      }
288	      throw t;
289	    } finally {
290	      // Keeping track of the fetcher here and calling cleanup is excessively paranoid, we call
291	      // close in all cases anyway.
292	      if (localFetcher != null) {
293	        localFetcher.cleanup();
294	      }
295	      GlideTrace.endSection();
296	    }
297	  }
