356	  /**
357	   * Restores the OS priority of the Glide thread to the default thread priority of {@link
358	   * com.bumptech.glide.load.engine.executor.GlideExecutor}.
359	   */
360	  private void restoreThreadPriority() {
361	    if (!experiments.isEnabled(OverrideGlideThreadPriority.class)) {
362	      throw new IllegalStateException("OverrideGlideThreadPriority experiment is not enabled.");
363	    }
364	    if (glideThreadPriorityOverride != null && glideThreadPriorityOverride.get() != null) {
365	      try {
366	        Process.setThreadPriority(Process.myTid(), GlideExecutor.DEFAULT_PRIORITY);
367	      } catch (IllegalArgumentException | SecurityException e) {
368	        glideThreadPriorityOverride = null;
369	        if (Log.isLoggable(TAG, Log.VERBOSE)) {
370	          Log.v(
371	              TAG,
372	              "Failed to set thread priority; using default priority for any subsequent jobs.",
373	              e);
374	        }
375	      }
376	    }
377	  }
378	
379	  private void notifyFailed() {
380	    if (experiments.isEnabled(OverrideGlideThreadPriority.class)) {
381	      restoreThreadPriority();
382	    }
383	    setNotifiedOrThrow();
384	    GlideException e = new GlideException("Failed to load resource", new ArrayList<>(throwables));
385	    callback.onLoadFailed(e);
386	    onLoadFailed();
387	  }
388	
389	  private void notifyComplete(
390	      Resource<R> resource, DataSource dataSource, boolean isLoadedFromAlternateCacheKey) {
391	    if (experiments.isEnabled(OverrideGlideThreadPriority.class)) {
392	      restoreThreadPriority();
393	    }
394	    setNotifiedOrThrow();
395	    callback.onResourceReady(resource, dataSource, isLoadedFromAlternateCacheKey);
396	  }
397	
398	  private void setNotifiedOrThrow() {
399	    stateVerifier.throwIfRecycled();
400	    if (isCallbackNotified) {
401	      Throwable lastThrown = throwables.isEmpty() ? null : throwables.get(throwables.size() - 1);
402	      throw new IllegalStateException("Already notified", lastThrown);
403	    }
404	    isCallbackNotified = true;
405	  }
