407	  private Stage getNextStage(Stage current) {
408	    switch (current) {
409	      case INITIALIZE:
410	        return diskCacheStrategy.decodeCachedResource()
411	            ? Stage.RESOURCE_CACHE
412	            : getNextStage(Stage.RESOURCE_CACHE);
413	      case RESOURCE_CACHE:
414	        return diskCacheStrategy.decodeCachedData()
415	            ? Stage.DATA_CACHE
416	            : getNextStage(Stage.DATA_CACHE);
417	      case DATA_CACHE:
418	        // Skip loading from source if the user opted to only retrieve the resource from cache.
419	        return onlyRetrieveFromCache ? Stage.FINISHED : Stage.SOURCE;
420	      case SOURCE:
421	      case FINISHED:
422	        return Stage.FINISHED;
423	      default:
424	        throw new IllegalArgumentException("Unrecognized stage: " + current);
425	    }
426	  }
