462	  @Override
463	  public void onDataFetcherFailed(
464	      Key attemptedKey, Exception e, DataFetcher<?> fetcher, DataSource dataSource) {
465	    fetcher.cleanup();
466	    GlideException exception = new GlideException("Fetching data failed", e);
467	    exception.setLoggingDetails(attemptedKey, dataSource, fetcher.getDataClass());
468	    throwables.add(exception);
469	    if (Thread.currentThread() != currentThread) {
470	      reschedule(RunReason.SWITCH_TO_SOURCE_SERVICE);
471	    } else {
472	      runGenerators();
473	    }
474	  }
