713	  /**
714	   * Returns {@code true} if the decoded and transformed resource is eligible to be written to the
715	   * resource disk cache.
716	   *
717	   * <p>When {@link GlideBuilder.BypassResourceDiskCacheForHardwareBitmaps} is enabled, resources
718	   * backed by {@link Bitmap.Config#HARDWARE} bitmaps are never written. Compressing a hardware
719	   * bitmap requires the framework to copy its pixels out of graphics memory into a software bitmap
720	   * ({@code RenderProxy#copyHWBitmapInto}). That copy runs on this job's thread after the resource
721	   * has been delivered, round-trips through the RenderThread (contending with frame rendering),
722	   * holds the {@link LockedResource} until it finishes, and transiently allocates a second,
723	   * full-size copy of the image in native memory.
724	   */
725	  private <Z> boolean isResourceCacheable(
726	      boolean isFromAlternateCacheKey,
727	      DataSource dataSource,
728	      EncodeStrategy encodeStrategy,
729	      Resource<Z> transformed) {
730	    if (!diskCacheStrategy.isResourceCacheable(
731	        isFromAlternateCacheKey, dataSource, encodeStrategy)) {
732	      return false;
733	    }
734	    if (experiments.isEnabled(GlideBuilder.BypassResourceDiskCacheForHardwareBitmaps.class)
735	        && isHardwareBitmap(transformed)) {
736	      return false;
737	    }
738	    return true;
739	  }
740	
741	  private static boolean isHardwareBitmap(Resource<?> resource) {
742	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
743	      return false;
744	    }
745	    Object content = resource.get();
746	    Bitmap bitmap = null;
747	    if (content instanceof Bitmap) {
748	      bitmap = (Bitmap) content;
749	    } else if (content instanceof BitmapDrawable) {
750	      bitmap = ((BitmapDrawable) content).getBitmap();
751	    }
752	    return bitmap != null && bitmap.getConfig() == Bitmap.Config.HARDWARE;
753	  }
754	
755	  /**
756	   * Returns {@code true} if we should bypass applying software transformations to the decoded
757	   * resource.
758	   *
759	   * <p>This is only true if the resource is a hardware bitmap, and both ALLOW_HARDWARE_CONFIG and
760	   * BYPASS_TRANSFORMATIONS_FOR_HARDWARE_BITMAPS options are enabled.
761	   */
762	  private <Z> boolean shouldBypassSoftwareTransformation(
763	      Resource<Z> decoded, Transformation<Z> transformation) {
764	    Boolean bypassOption = options.get(Downsampler.BYPASS_TRANSFORMATIONS_FOR_HARDWARE_BITMAPS);
765	    if (bypassOption == null || !bypassOption) {
766	      return false;
767	    }
768	
769	    Boolean allowHardware = options.get(Downsampler.ALLOW_HARDWARE_CONFIG);
770	    if (allowHardware == null || !allowHardware) {
771	      return false;
772	    }
773	
774	    return isHardwareBitmap(decoded);
775	  }
