243	  private <R> LoadStatus waitForExistingOrStartNewJob(
244	      GlideContext glideContext,
245	      Object model,
246	      Key signature,
247	      int width,
248	      int height,
249	      Class<?> resourceClass,
250	      Class<R> transcodeClass,
251	      Priority priority,
252	      DiskCacheStrategy diskCacheStrategy,
253	      Map<Class<?>, Transformation<?>> transformations,
254	      boolean isTransformationRequired,
255	      boolean isScaleOnlyOrNoTransform,
256	      Options options,
257	      boolean isMemoryCacheable,
258	      boolean useUnlimitedSourceExecutorPool,
259	      boolean useAnimationPool,
260	      boolean onlyRetrieveFromCache,
261	      ResourceCallback cb,
262	      Executor callbackExecutor,
263	      EngineKey key,
264	      long startTime) {
265	
266	    EngineJob<?> current = jobs.get(key, onlyRetrieveFromCache);
267	    if (current != null) {
268	      current.addCallback(cb, callbackExecutor);
269	      if (VERBOSE_IS_LOGGABLE) {
270	        logWithTimeAndKey("Added to existing load", startTime, key);
271	      }
272	      return new LoadStatus(cb, current);
273	    }
274	
275	    EngineJob<R> engineJob =
276	        engineJobFactory.build(
277	            key,
278	            isMemoryCacheable,
279	            useUnlimitedSourceExecutorPool,
280	            useAnimationPool,
281	            onlyRetrieveFromCache);
282	
283	    DecodeJob<R> decodeJob =
284	        decodeJobFactory.build(
285	            glideContext,
286	            model,
287	            key,
288	            signature,
289	            width,
290	            height,
291	            resourceClass,
292	            transcodeClass,
293	            priority,
294	            diskCacheStrategy,
295	            transformations,
296	            isTransformationRequired,
297	            isScaleOnlyOrNoTransform,
298	            onlyRetrieveFromCache,
299	            options,
300	            engineJob);
301	
302	    jobs.put(key, engineJob);
303	
304	    engineJob.addCallback(cb, callbackExecutor);
305	    engineJob.start(decodeJob);
306	
307	    if (VERBOSE_IS_LOGGABLE) {
308	      logWithTimeAndKey("Started new load", startTime, key);
309	    }
310	    return new LoadStatus(cb, engineJob);
311	  }
