313	  @Nullable
314	  private EngineResource<?> loadFromMemory(
315	      EngineKey key, boolean isMemoryCacheable, boolean isReleaseRaceFixEnabled, long startTime) {
316	    if (!isMemoryCacheable) {
317	      return null;
318	    }
319	
320	    EngineResource<?> active = loadFromActiveResources(key, isReleaseRaceFixEnabled);
321	    if (active != null) {
322	      if (VERBOSE_IS_LOGGABLE) {
323	        logWithTimeAndKey("Loaded resource from active resources", startTime, key);
324	      }
325	      if (Log.isLoggable(GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
326	        logCacheHit("active", key, active);
327	      }
328	      return active;
329	    }
330	
331	    EngineResource<?> cached = loadFromCache(key);
332	    if (cached != null) {
333	      if (VERBOSE_IS_LOGGABLE) {
334	        logWithTimeAndKey("Loaded resource from cache", startTime, key);
335	      }
336	      if (Log.isLoggable(GLIDE_MEMORY_TRACKING_TAG, Log.DEBUG)) {
337	        logCacheHit("cache", key, cached);
338	      }
339	      return cached;
340	    }
341	
342	    return null;
343	  }
344	
345	  private static void logWithTimeAndKey(String log, long startTime, Key key) {
346	    Log.v(TAG, log + " in " + LogTime.getElapsedMillis(startTime) + "ms, key: " + key);
347	  }
