405	  private EngineResource<?> loadFromCache(Key key) {
406	    EngineResource<?> cached = getEngineResourceFromCache(key);
407	    if (cached != null) {
408	      cached.acquire();
409	      activeResources.activate(key, cached);
410	    }
411	    return cached;
412	  }
413	
414	  private EngineResource<?> getEngineResourceFromCache(Key key) {
415	    Resource<?> cached = cache.remove(key);
416	
417	    final EngineResource<?> result;
418	    if (cached == null) {
419	      result = null;
420	    } else if (cached instanceof EngineResource) {
421	      // Save an object allocation if we've cached an EngineResource (the typical case).
422	      result = (EngineResource<?>) cached;
423	    } else {
424	      result =
425	          new EngineResource<>(
426	              cached,
427	              /* isMemoryCacheable= */ true,
428	              /* isRecyclable= */ true,
429	              key,
430	              /* listener= */ this);
431	    }
432	    return result;
433	  }
