488	  /**
489	   * Allows a request to indicate it no longer is interested in a given load.
490	   *
491	   * <p>Non-final for mocking.
492	   */
493	  public class LoadStatus {
494	    private final EngineJob<?> engineJob;
495	    private final ResourceCallback cb;
496	
497	    LoadStatus(ResourceCallback cb, EngineJob<?> engineJob) {
498	      this.cb = cb;
499	      this.engineJob = engineJob;
500	    }
501	
502	    public void cancel() {
503	      // Acquire the Engine lock so that a new request can't get access to a particular EngineJob
504	      // just after the EngineJob has been cancelled. Without this lock, we'd allow new requests
505	      // to find the cancelling EngineJob in our Jobs data structure. With this lock, the EngineJob
506	      // is both cancelled and removed from Jobs atomically.
507	      synchronized (Engine.this) {
508	        engineJob.removeCallback(cb);
509	      }
510	    }
511	  }
