342	  // We have to post Runnables in a loop. Typically there will be very few callbacks. Acessor method
343	  // warning seems to be false positive.
344	  @SuppressWarnings({
345	    "WeakerAccess",
346	    "PMD.AvoidInstantiatingObjectsInLoops",
347	    "PMD.AccessorMethodGeneration"
