387	  private class CallLoadFailed implements Runnable {
388	
389	    private final ResourceCallback cb;
390	
391	    CallLoadFailed(ResourceCallback cb) {
392	      this.cb = cb;
393	    }
394	
395	    @Override
396	    public void run() {
397	      // Make sure we always acquire the request lock, then the EngineJob lock to avoid deadlock
398	      // (b/136032534).
399	      synchronized (cb.getLock()) {
400	        synchronized (EngineJob.this) {
401	          if (cbs.contains(cb)) {
402	            callCallbackOnLoadFailed(cb);
403	          }
404	
405	          decrementPendingCallbacks();
406	        }
407	      }
408	    }
409	  }
