96	          // Context#createPackageContext may return a Context without an Application instance,
97	          // in which case a ContextWrapper may be used to attach one.
98	          && ((ContextWrapper) context).getBaseContext().getApplicationContext() != null) {
99	        return get(((ContextWrapper) context).getBaseContext());
