156	  @NonNull
157	  public RequestManager get(@NonNull View view) {
158	    if (Util.isOnBackgroundThread()) {
159	      return get(view.getContext().getApplicationContext());
160	    }
161	
162	    Preconditions.checkNotNull(view);
163	    Preconditions.checkNotNull(
164	        view.getContext(), "Unable to obtain a request manager for a view without a Context");
