2	
3	import android.util.Log;
4	import androidx.annotation.NonNull;
5	import androidx.core.util.Pools.Pool;
6	import com.bumptech.glide.load.Options;
7	import com.bumptech.glide.load.ResourceDecoder;
8	import com.bumptech.glide.load.data.DataRewinder;
9	import com.bumptech.glide.load.resource.transcode.ResourceTranscoder;
10	import com.bumptech.glide.util.Preconditions;
11	import java.io.IOException;
12	import java.util.ArrayList;
13	import java.util.List;
14	
15	/**
16	 * Attempts to decode and transcode resource type from a given data type.
17	 *
18	 * @param <DataType> The type of data ResourceType that will be decoded from.
19	 * @param <ResourceType> The type of intermediate resource that will be decoded.
20	 * @param <Transcode> The final type of resource that will be transcoded from ResourceType and
21	 *     returned to the caller.
22	 */
23	public class DecodePath<DataType, ResourceType, Transcode> {
24	  private static final String TAG = "DecodePath";
25	  private final Class<DataType> dataClass;
26	  private final List<? extends ResourceDecoder<DataType, ResourceType>> decoders;
27	  private final ResourceTranscoder<ResourceType, Transcode> transcoder;
28	  private final Pool<List<Throwable>> listPool;
29	  private final String failureMessage;
30	
31	  public DecodePath(
32	      Class<DataType> dataClass,
33	      Class<ResourceType> resourceClass,
34	      Class<Transcode> transcodeClass,
35	      List<? extends ResourceDecoder<DataType, ResourceType>> decoders,
36	      ResourceTranscoder<ResourceType, Transcode> transcoder,
37	      Pool<List<Throwable>> listPool) {
38	    this.dataClass = dataClass;
39	    this.decoders = decoders;
40	    this.transcoder = transcoder;
41	    this.listPool = listPool;
42	    failureMessage =
43	        "Failed DecodePath{"
44	            + dataClass.getSimpleName()
45	            + "->"
46	            + resourceClass.getSimpleName()
47	            + "->"
48	            + transcodeClass.getSimpleName()
49	            + "}";
50	  }
51	
52	  public Resource<Transcode> decode(
53	      DataRewinder<DataType> rewinder,
54	      int width,
55	      int height,
56	      @NonNull Options options,
57	      DecodeCallback<ResourceType> callback)
58	      throws GlideException {
59	    Resource<ResourceType> decoded = decodeResource(rewinder, width, height, options);
60	    Resource<ResourceType> transformed = callback.onResourceDecoded(decoded);
61	    return transcoder.transcode(transformed, options);
62	  }
63	
64	  @NonNull
65	  private Resource<ResourceType> decodeResource(
66	      DataRewinder<DataType> rewinder, int width, int height, @NonNull Options options)
67	      throws GlideException {
68	    List<Throwable> exceptions = Preconditions.checkNotNull(listPool.acquire());
69	    try {
70	      return decodeResourceWithList(rewinder, width, height, options, exceptions);
71	    } finally {
72	      listPool.release(exceptions);
73	    }
74	  }
75	
76	  @NonNull
77	  private Resource<ResourceType> decodeResourceWithList(
78	      DataRewinder<DataType> rewinder,
79	      int width,
80	      int height,
81	      @NonNull Options options,
82	      List<Throwable> exceptions)
83	      throws GlideException {
84	    Resource<ResourceType> result = null;
85	    //noinspection ForLoopReplaceableByForEach to improve perf
86	    for (int i = 0, size = decoders.size(); i < size; i++) {
87	      ResourceDecoder<DataType, ResourceType> decoder = decoders.get(i);
88	      try {
89	        DataType data = rewinder.rewindAndGet();
90	        if (decoder.handles(data, options)) {
91	          data = rewinder.rewindAndGet();
92	          result = decoder.decode(data, width, height, options);
93	        }
94	        // Some decoders throw unexpectedly. If they do, we shouldn't fail the entire load path, but
95	        // instead log and continue. See #2406 for an example.
96	      } catch (IOException | RuntimeException | OutOfMemoryError e) {
97	        if (Log.isLoggable(TAG, Log.VERBOSE)) {
98	          Log.v(TAG, "Failed to decode data for " + decoder, e);
99	        }
100	        exceptions.add(e);
101	      }
102	
103	      if (result != null) {
104	        break;
105	      }
106	    }
107	
108	    if (result == null) {
109	      throw new GlideException(failureMessage, new ArrayList<>(exceptions));
110	    }
111	    return result;
112	  }
113	
114	  @Override
115	  public String toString() {
116	    return "DecodePath{"
117	        + " dataClass="
118	        + dataClass
119	        + ", decoders="
120	        + decoders
121	        + ", transcoder="
122	        + transcoder
123	        + '}';
124	  }
125	
126	  interface DecodeCallback<ResourceType> {
127	    @NonNull
128	    Resource<ResourceType> onResourceDecoded(@NonNull Resource<ResourceType> resource);
129	  }
130	}
