96	  @Nullable
97	  private GifDrawableResource decode(
98	      ByteBuffer byteBuffer, int width, int height, GifHeaderParser parser, Options options) {
99	    long startTime = LogTime.getLogTime();
100	    try {
101	      final GifHeader header = parser.parseHeader();
102	      if (header.getNumFrames() <= 0 || header.getStatus() != GifDecoder.STATUS_OK) {
103	        // If we couldn't decode the GIF, we will end up with a frame count of 0.
104	        return null;
105	      }
106	
107	      Bitmap.Config config =
108	          options.get(GifOptions.DECODE_FORMAT) == DecodeFormat.PREFER_RGB_565
109	              ? Bitmap.Config.RGB_565
110	              : Bitmap.Config.ARGB_8888;
111	
112	      int sampleSize = getSampleSize(header, width, height);
113	      GifDecoder gifDecoder = gifDecoderFactory.build(provider, header, byteBuffer, sampleSize);
114	      gifDecoder.setDefaultBitmapConfig(config);
115	      gifDecoder.advance();
116	      Bitmap firstFrame = gifDecoder.getNextFrame();
117	      if (firstFrame == null) {
118	        return null;
119	      }
120	
121	      Transformation<Bitmap> unitTransformation = UnitTransformation.get();
122	
123	      GifDrawable gifDrawable =
124	          new GifDrawable(context, gifDecoder, unitTransformation, width, height, firstFrame);
125	
126	      return new GifDrawableResource(gifDrawable);
127	    } finally {
128	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
129	        Log.v(TAG, "Decoded GIF from stream in " + LogTime.getElapsedMillis(startTime));
130	      }
131	    }
132	  }
133	
134	  private static int getSampleSize(GifHeader gifHeader, int targetWidth, int targetHeight) {
135	    int exactSampleSize =
136	        Math.min(gifHeader.getHeight() / targetHeight, gifHeader.getWidth() / targetWidth);
137	    int powerOfTwoSampleSize = exactSampleSize == 0 ? 0 : Integer.highestOneBit(exactSampleSize);
138	    // Although functionally equivalent to 0 for BitmapFactory, 1 is a safer default for our code
139	    // than 0.
140	    int sampleSize = Math.max(1, powerOfTwoSampleSize);
141	    if (Log.isLoggable(TAG, Log.VERBOSE) && sampleSize > 1) {
142	      Log.v(
143	          TAG,
144	          "Downsampling GIF"
145	              + ", sampleSize: "
146	              + sampleSize
147	              + ", target dimens: ["
148	              + targetWidth
149	              + "x"
150	              + targetHeight
151	              + "]"
152	              + ", actual dimens: ["
153	              + gifHeader.getWidth()
154	              + "x"
155	              + gifHeader.getHeight()
156	              + "]");
157	    }
158	    return sampleSize;
159	  }
160	
161	  @VisibleForTesting
162	  static class GifDecoderFactory {
163	    GifDecoder build(
164	        GifDecoder.BitmapProvider provider, GifHeader header, ByteBuffer data, int sampleSize) {
165	      return new StandardGifDecoder(provider, header, data, sampleSize);
166	    }
167	  }
168	
169	  @VisibleForTesting
170	  static class GifHeaderParserPool {
171	    private final Queue<GifHeaderParser> pool = Util.createQueue(0);
172	
173	    synchronized GifHeaderParser obtain(ByteBuffer buffer) {
174	      GifHeaderParser result = pool.poll();
175	      if (result == null) {
176	        result = new GifHeaderParser();
177	      }
178	      return result.setData(buffer);
179	    }
180	
181	    synchronized void release(GifHeaderParser parser) {
182	      parser.clear();
183	      pool.offer(parser);
184	    }
185	  }
186	}
