714	  /**
715	   * BitmapFactory calculates the density scale factor as a float. This introduces some non-trivial
716	   * error. This method attempts to account for that error by adjusting the inTargetDensity so that
717	   * the final scale factor is as close to our target as possible.
718	   */
719	  private static int adjustTargetDensityForError(double adjustedScaleFactor) {
720	    int densityMultiplier = getDensityMultiplier(adjustedScaleFactor);
721	    int targetDensity = round(densityMultiplier * adjustedScaleFactor);
722	    float scaleFactorWithError = targetDensity / (float) densityMultiplier;
723	    double difference = adjustedScaleFactor / scaleFactorWithError;
724	    return round(difference * targetDensity);
725	  }
726	
727	  private static int getDensityMultiplier(double adjustedScaleFactor) {
728	    return (int)
729	        Math.round(
730	            Integer.MAX_VALUE
731	                * (adjustedScaleFactor <= 1D ? adjustedScaleFactor : 1 / adjustedScaleFactor));
732	  }
