740	  private boolean shouldUsePool(ImageType imageType) {
741	    // On KitKat+, any bitmap (of a given config) can be used to decode any other bitmap
742	    // (with the same config).
743	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
744	      return true;
745	    }
746	
747	    // We cannot reuse bitmaps when decoding images that are not PNG or JPG prior to KitKat.
748	    // See: https://groups.google.com/forum/#!msg/android-developers/Mp0MFVFi1Fo/e8ZQ9FGdWdEJ
749	    return TYPES_THAT_USE_POOL_PRE_KITKAT.contains(imageType);
750	  }
