752	  @SuppressWarnings("deprecation")
753	  private void calculateConfig(
754	      ImageReader imageReader,
755	      DecodeFormat format,
756	      boolean isHardwareConfigAllowed,
757	      boolean isExifOrientationRequired,
758	      BitmapFactory.Options optionsWithScaling,
759	      int targetWidth,
760	      int targetHeight) {
761	
762	    if (hardwareConfigState.setHardwareConfigIfAllowed(
763	        targetWidth,
764	        targetHeight,
765	        optionsWithScaling,
766	        isHardwareConfigAllowed,
767	        isExifOrientationRequired)) {
768	      return;
769	    }
770	
771	    // Changing configs can cause skewing on 4.1, see issue #128.
772	    if (format == DecodeFormat.PREFER_ARGB_8888
773	        || Build.VERSION.SDK_INT == Build.VERSION_CODES.JELLY_BEAN) {
774	      optionsWithScaling.inPreferredConfig = Bitmap.Config.ARGB_8888;
775	      return;
776	    }
777	
778	    boolean hasAlpha = false;
779	    try {
780	      hasAlpha = imageReader.getImageType().hasAlpha();
781	    } catch (IOException e) {
782	      if (Log.isLoggable(TAG, Log.DEBUG)) {
783	        Log.d(
784	            TAG,
785	            "Cannot determine whether the image has alpha or not from header"
786	                + ", format "
787	                + format,
788	            e);
789	      }
790	    }
791	
792	    optionsWithScaling.inPreferredConfig =
793	        hasAlpha ? Bitmap.Config.ARGB_8888 : Bitmap.Config.RGB_565;
794	    if (optionsWithScaling.inPreferredConfig == Config.RGB_565) {
795	      optionsWithScaling.inDither = true;
796	    }
797	  }
