799	  /**
800	   * A method for getting the dimensions of an image from the given InputStream.
801	   *
802	   * @param imageReader The {@link ImageReader} representing the image.
803	   * @param options The options to pass to {@link BitmapFactory#decodeStream(java.io.InputStream,
804	   *     android.graphics.Rect, android.graphics.BitmapFactory.Options)}.
805	   * @return an array containing the dimensions of the image in the form {width, height}.
806	   */
807	  private static int[] getDimensions(
808	      ImageReader imageReader,
809	      BitmapFactory.Options options,
810	      DecodeCallbacks decodeCallbacks,
811	      BitmapPool bitmapPool)
812	      throws IOException {
813	    options.inJustDecodeBounds = true;
814	    decodeStream(imageReader, options, decodeCallbacks, bitmapPool);
815	    options.inJustDecodeBounds = false;
816	    return new int[] {options.outWidth, options.outHeight};
817	  }
818	
819	  private static Bitmap decodeStream(
820	      ImageReader imageReader,
821	      BitmapFactory.Options options,
822	      DecodeCallbacks callbacks,
823	      BitmapPool bitmapPool)
824	      throws IOException {
825	    if (!options.inJustDecodeBounds) {
826	      // Once we've read the image header, we no longer need to allow the buffer to expand in
827	      // size. To avoid unnecessary allocations reading image data, we fix the mark limit so that it
828	      // is no larger than our current buffer size here. We need to do so immediately before
829	      // decoding the full image to avoid having our mark limit overridden by other calls to
830	      // mark and reset. See issue #225.
831	      callbacks.onObtainBounds();
832	      imageReader.stopGrowingBuffers();
833	    }
834	
835	    // BitmapFactory.Options out* variables are reset by most calls to decodeStream, successful or
836	    // otherwise, so capture here in case we log below.
837	    int sourceWidth = options.outWidth;
838	    int sourceHeight = options.outHeight;
839	    String outMimeType = options.outMimeType;
840	    final Bitmap result;
841	    TransformationUtils.getBitmapDrawableLock().lock();
842	    try {
843	      result = imageReader.decodeBitmap(options);
844	    } catch (IllegalArgumentException e) {
845	      IOException bitmapAssertionException =
846	          newIoExceptionForInBitmapAssertion(e, sourceWidth, sourceHeight, outMimeType, options);
847	      if (Log.isLoggable(TAG, Log.DEBUG)) {
848	        Log.d(
849	            TAG,
850	            "Failed to decode with inBitmap, trying again without Bitmap re-use",
851	            bitmapAssertionException);
852	      }
853	      if (options.inBitmap != null) {
854	        try {
855	          bitmapPool.put(options.inBitmap);
856	          options.inBitmap = null;
857	          return decodeStream(imageReader, options, callbacks, bitmapPool);
858	        } catch (IOException resetException) {
859	          throw bitmapAssertionException;
860	        }
861	      }
862	      throw bitmapAssertionException;
863	    } finally {
864	      TransformationUtils.getBitmapDrawableLock().unlock();
865	    }
866	
867	    return result;
868	  }
