939	  // file when inBitmap is non-null, including those caused by partial or corrupt data. We still log
940	  // the error because the IllegalArgumentException is supposed to catch errors reusing Bitmaps, so
941	  // want some useful log output. In most cases this can be safely treated as a normal IOException.
942	  private static IOException newIoExceptionForInBitmapAssertion(
943	      IllegalArgumentException e,
944	      int outWidth,
945	      int outHeight,
946	      String outMimeType,
947	      BitmapFactory.Options options) {
