961	  @SuppressWarnings("PMD.CollapsibleIfStatements")
962	  @TargetApi(Build.VERSION_CODES.O)
963	  private static void setInBitmap(
964	      BitmapFactory.Options options,
965	      BitmapPool bitmapPool,
966	      int width,
967	      int height,
968	      @Nullable GlideExperiments experiments) {
969	    @Nullable Bitmap.Config expectedConfig = null;
970	    // Avoid short circuiting, it appears to break on some devices.
971	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
972	      if (options.inPreferredConfig == Config.HARDWARE) {
973	        return;
974	      }
975	      // On API 26 outConfig may be null for some images even if the image is valid, can be decoded
976	      // and outWidth/outHeight/outColorSpace are populated (see b/71513049).
977	      expectedConfig = options.outConfig;
978	
979	      // If we have a standard image (not wide gamut) and we're requesting RGB_565, avoid allocating
980	      // more space than necessary.
981	      if (expectedConfig == Config.ARGB_8888 && options.inPreferredConfig == Config.RGB_565) {
982	        if (experiments != null
983	            && experiments.isEnabled(GlideBuilder.EnableRgb565DownsamplerFix.class)) {
984	          expectedConfig = Config.RGB_565;
985	        }
986	      }
987	    }
988	
989	    if (expectedConfig == null) {
990	      // We're going to guess that BitmapFactory will return us the config we're requesting. This
991	      // isn't always the case, even though our guesses tend to be conservative and prefer configs
992	      // of larger sizes so that the Bitmap will fit our image anyway. If we're wrong here and the
993	      // config we choose is too small, our initial decode will fail, but we will retry with no
994	      // inBitmap which will succeed so if we're wrong here, we're less efficient but still correct.
995	      expectedConfig = options.inPreferredConfig;
996	    }
997	    // BitmapFactory will clear out the Bitmap before writing to it, so getDirty is safe.
998	    options.inBitmap = bitmapPool.getDirty(width, height, expectedConfig);
999	  }
