7	/**
8	 * An Android Lifecycle wrapper that uses {@link SingletonConnectivityReceiver} to observer
9	 * connectivity changes, allowing for registration to be removed when our listener is being
10	 * destroyed as part of the Android lifecycle.
11	 */
12	final class DefaultConnectivityMonitor implements ConnectivityMonitor {
13	  private final Context context;
14	
15	  @SuppressWarnings("WeakerAccess")
16	  @Synthetic
17	  final ConnectivityListener listener;
18	
19	  DefaultConnectivityMonitor(@NonNull Context context, @NonNull ConnectivityListener listener) {
20	    this.context = context.getApplicationContext();
21	    this.listener = listener;
22	  }
23	
24	  private void register() {
25	    SingletonConnectivityReceiver.get(context).register(listener);
26	  }
27	
28	  private void unregister() {
29	    SingletonConnectivityReceiver.get(context).unregister(listener);
30	  }
31	
32	  @Override
33	  public void onStart() {
34	    register();
35	  }
36	
37	  @Override
38	  public void onStop() {
39	    unregister();
40	  }
41	
42	  @Override
43	  public void onDestroy() {
44	    // Do nothing.
45	  }
46	}
