1	package com.bumptech.glide.load.engine.bitmap_recycle;
2	
3	import android.graphics.Bitmap;
4	import android.graphics.Bitmap.Config;
5	import android.os.Build;
6	import androidx.annotation.Nullable;
7	import androidx.annotation.RequiresApi;
8	import androidx.annotation.VisibleForTesting;
9	import com.bumptech.glide.util.Synthetic;
10	import com.bumptech.glide.util.Util;
11	import java.util.Arrays;
12	import java.util.HashMap;
13	import java.util.Map;
14	import java.util.NavigableMap;
15	import java.util.TreeMap;
16	
17	/**
18	 * Keys {@link android.graphics.Bitmap Bitmaps} using both {@link
19	 * android.graphics.Bitmap#getAllocationByteCount()} and the {@link android.graphics.Bitmap.Config}
20	 * returned from {@link android.graphics.Bitmap#getConfig()}.
21	 *
22	 * <p>Using both the config and the byte size allows us to safely re-use a greater variety of {@link
23	 * android.graphics.Bitmap Bitmaps}, which increases the hit rate of the pool and therefore the
24	 * performance of applications. This class works around #301 by only allowing re-use of {@link
25	 * android.graphics.Bitmap Bitmaps} with a matching number of bytes per pixel.
26	 */
27	@RequiresApi(Build.VERSION_CODES.KITKAT)
28	public class SizeConfigStrategy implements LruPoolStrategy {
29	  private static final int MAX_SIZE_MULTIPLE = 8;
30	
31	  private static final Bitmap.Config[] ARGB_8888_IN_CONFIGS;
32	
33	  static {
34	    Bitmap.Config[] result =
35	        new Bitmap.Config[] {
36	          Bitmap.Config.ARGB_8888,
37	          // The value returned by Bitmaps with the hidden Bitmap config.
38	          null,
39	        };
40	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
41	      result = Arrays.copyOf(result, result.length + 1);
42	      result[result.length - 1] = Config.RGBA_F16;
43	    }
44	    ARGB_8888_IN_CONFIGS = result;
45	  }
46	
47	  private static final Bitmap.Config[] RGBA_F16_IN_CONFIGS = ARGB_8888_IN_CONFIGS;
48	
49	  // We probably could allow ARGB_4444 and RGB_565 to decode into each other, but ARGB_4444 is
50	  // deprecated and we'd rather be safe.
51	  private static final Bitmap.Config[] RGB_565_IN_CONFIGS =
52	      new Bitmap.Config[] {Bitmap.Config.RGB_565};
53	  private static final Bitmap.Config[] ARGB_4444_IN_CONFIGS =
54	      new Bitmap.Config[] {Bitmap.Config.ARGB_4444};
55	  private static final Bitmap.Config[] ALPHA_8_IN_CONFIGS =
56	      new Bitmap.Config[] {Bitmap.Config.ALPHA_8};
57	
58	  private final KeyPool keyPool = new KeyPool();
59	  private final GroupedLinkedMap<Key, Bitmap> groupedMap = new GroupedLinkedMap<>();
60	  private final Map<Bitmap.Config, NavigableMap<Integer, Integer>> sortedSizes = new HashMap<>();
61	
62	  @Override
63	  public void put(Bitmap bitmap) {
64	    int size = Util.getBitmapByteSize(bitmap);
65	    Key key = keyPool.get(size, bitmap.getConfig());
66	
67	    groupedMap.put(key, bitmap);
68	
69	    NavigableMap<Integer, Integer> sizes = getSizesForConfig(bitmap.getConfig());
70	    Integer current = sizes.get(key.size);
71	    sizes.put(key.size, current == null ? 1 : current + 1);
72	  }
73	
74	  @Override
75	  @Nullable
76	  public Bitmap get(int width, int height, Bitmap.Config config) {
77	    int size = Util.getBitmapByteSize(width, height, config);
78	    Key bestKey = findBestKey(size, config);
79	
80	    Bitmap result = groupedMap.get(bestKey);
81	    if (result != null) {
82	      // Decrement must be called before reconfigure.
83	      decrementBitmapOfSize(bestKey.size, result);
84	      result.reconfigure(width, height, config);
85	    }
86	    return result;
87	  }
88	
89	  private Key findBestKey(int size, Bitmap.Config config) {
90	    Key result = keyPool.get(size, config);
91	    for (Bitmap.Config possibleConfig : getInConfigs(config)) {
92	      NavigableMap<Integer, Integer> sizesForPossibleConfig = getSizesForConfig(possibleConfig);
93	      Integer possibleSize = sizesForPossibleConfig.ceilingKey(size);
94	      if (possibleSize != null && possibleSize <= size * MAX_SIZE_MULTIPLE) {
95	        if (possibleSize != size
96	            || (possibleConfig == null ? config != null : !possibleConfig.equals(config))) {
97	          keyPool.offer(result);
98	          result = keyPool.get(possibleSize, possibleConfig);
99	        }
100	        break;
101	      }
102	    }
103	    return result;
104	  }
105	
106	  @Override
107	  @Nullable
108	  public Bitmap removeLast() {
109	    Bitmap removed = groupedMap.removeLast();
110	    if (removed != null) {
111	      int removedSize = Util.getBitmapByteSize(removed);
112	      decrementBitmapOfSize(removedSize, removed);
113	    }
114	    return removed;
115	  }
116	
117	  private void decrementBitmapOfSize(Integer size, Bitmap removed) {
118	    Bitmap.Config config = removed.getConfig();
119	    NavigableMap<Integer, Integer> sizes = getSizesForConfig(config);
120	    Integer current = sizes.get(size);
121	    if (current == null) {
122	      throw new NullPointerException(
123	          "Tried to decrement empty size"
124	              + ", size: "
125	              + size
126	              + ", removed: "
127	              + logBitmap(removed)
128	              + ", this: "
129	              + this);
130	    }
131	
132	    if (current == 1) {
133	      sizes.remove(size);
134	    } else {
135	      sizes.put(size, current - 1);
136	    }
137	  }
138	
139	  private NavigableMap<Integer, Integer> getSizesForConfig(Bitmap.Config config) {
140	    NavigableMap<Integer, Integer> sizes = sortedSizes.get(config);
141	    if (sizes == null) {
142	      sizes = new TreeMap<>();
143	      sortedSizes.put(config, sizes);
144	    }
145	    return sizes;
146	  }
147	
148	  @Override
149	  public String logBitmap(Bitmap bitmap) {
150	    int size = Util.getBitmapByteSize(bitmap);
151	    return getBitmapString(size, bitmap.getConfig());
152	  }
153	
154	  @Override
155	  public String logBitmap(int width, int height, Bitmap.Config config) {
156	    int size = Util.getBitmapByteSize(width, height, config);
157	    return getBitmapString(size, config);
158	  }
159	
160	  @Override
161	  public int getSize(Bitmap bitmap) {
162	    return Util.getBitmapByteSize(bitmap);
163	  }
164	
165	  @Override
166	  public String toString() {
167	    StringBuilder sb =
168	        new StringBuilder()
169	            .append("SizeConfigStrategy{groupedMap=")
170	            .append(groupedMap)
171	            .append(", sortedSizes=(");
172	    for (Map.Entry<Bitmap.Config, NavigableMap<Integer, Integer>> entry : sortedSizes.entrySet()) {
173	      sb.append(entry.getKey()).append('[').append(entry.getValue()).append("], ");
174	    }
175	    if (!sortedSizes.isEmpty()) {
176	      sb.replace(sb.length() - 2, sb.length(), "");
177	    }
178	    return sb.append(")}").toString();
179	  }
180	
181	  @VisibleForTesting
182	  static class KeyPool extends BaseKeyPool<Key> {
183	
184	    public Key get(int size, Bitmap.Config config) {
185	      Key result = get();
186	      result.init(size, config);
187	      return result;
188	    }
189	
190	    @Override
191	    protected Key create() {
192	      return new Key(this);
193	    }
194	  }
195	
196	  @VisibleForTesting
197	  static final class Key implements Poolable {
198	    private final KeyPool pool;
199	
200	    @Synthetic int size;
201	    private Bitmap.Config config;
202	
203	    public Key(KeyPool pool) {
204	      this.pool = pool;
205	    }
206	
207	    @VisibleForTesting
208	    Key(KeyPool pool, int size, Bitmap.Config config) {
209	      this(pool);
210	      init(size, config);
211	    }
212	
213	    public void init(int size, Bitmap.Config config) {
214	      this.size = size;
215	      this.config = config;
216	    }
217	
218	    @Override
219	    public void offer() {
220	      pool.offer(this);
221	    }
222	
223	    @Override
224	    public String toString() {
225	      return getBitmapString(size, config);
226	    }
227	
228	    @Override
229	    public boolean equals(Object o) {
230	      if (o instanceof Key) {
231	        Key other = (Key) o;
232	        return size == other.size && Util.bothNullOrEqual(config, other.config);
233	      }
234	      return false;
235	    }
236	
237	    @Override
238	    public int hashCode() {
239	      int result = size;
240	      result = 31 * result + (config != null ? config.hashCode() : 0);
241	      return result;
242	    }
243	  }
244	
245	  @Synthetic
246	  static String getBitmapString(int size, Bitmap.Config config) {
247	    return "[" + size + "](" + config + ")";
248	  }
249	
250	  private static Bitmap.Config[] getInConfigs(Bitmap.Config requested) {
251	    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
252	      if (Bitmap.Config.RGBA_F16.equals(requested)) { // NOPMD - Avoid short circuiting sdk checks.
253	        return RGBA_F16_IN_CONFIGS;
254	      }
255	    }
256	
257	    switch (requested) {
258	      case ARGB_8888:
259	        return ARGB_8888_IN_CONFIGS;
260	      case RGB_565:
261	        return RGB_565_IN_CONFIGS;
262	      case ARGB_4444:
263	        return ARGB_4444_IN_CONFIGS;
264	      case ALPHA_8:
265	        return ALPHA_8_IN_CONFIGS;
266	      default:
267	        return new Bitmap.Config[] {requested};
268	    }
269	  }
270	}
