30	      Class<Data> dataClass,
31	      Class<ResourceType> resourceClass,
32	      Class<Transcode> transcodeClass,
33	      List<DecodePath<Data, ResourceType, Transcode>> decodePaths,
34	      Pool<List<Throwable>> listPool) {
