143	  /**
144	   * Starts a load for the given arguments.
145	   *
146	   * <p>Must be called on the main thread.
147	   *
148	   * <p>The flow for any request is as follows:
149	   *
150	   * <ul>

150	   * <ul>
151	   *   <li>Check the current set of actively used resources, return the active resource if present,
152	   *       and move any newly inactive resources into the memory cache.
153	   *   <li>Check the memory cache and provide the cached resource if present.
154	   *   <li>Check the current set of in progress loads and add the cb to the in progress load if one
155	   *       is present.
156	   *   <li>Start a new load.
157	   * </ul>
158	   *
159	   * <p>Active resources are those that have been provided to at least one request and have not yet
160	   * been released. Once all consumers of a resource have released that resource, the resource then
161	   * goes to cache. If the resource is ever returned to a new consumer from cache, it is re-added to
162	   * the active resources. If the resource is evicted from the cache, its resources are recycled and
163	   * re-used if possible and the resource is discarded. There is no strict requirement that
164	   * consumers release their resources so active resources are held weakly.
165	   *
166	   * @param width The target width in pixels of the desired resource.
167	   * @param height The target height in pixels of the desired resource.
168	   * @param cb The callback that will be called when the load completes.
169	   */
170	  public <R> LoadStatus load(
171	      GlideContext glideContext,
172	      Object model,
173	      Key signature,
174	      int width,
175	      int height,
176	      Class<?> resourceClass,
177	      Class<R> transcodeClass,
178	      Priority priority,
179	      DiskCacheStrategy diskCacheStrategy,
180	      Map<Class<?>, Transformation<?>> transformations,
181	      boolean isTransformationRequired,
182	      boolean isScaleOnlyOrNoTransform,
183	      Options options,
184	      boolean isMemoryCacheable,
185	      boolean useUnlimitedSourceExecutorPool,
186	      boolean useAnimationPool,
187	      boolean onlyRetrieveFromCache,
188	      ResourceCallback cb,
189	      Executor callbackExecutor) {
190	    long startTime = VERBOSE_IS_LOGGABLE ? LogTime.getLogTime() : 0;
191	
192	    EngineKey key =
193	        keyFactory.buildKey(
194	            model,
195	            signature,
196	            width,
197	            height,
198	            transformations,
199	            resourceClass,
200	            transcodeClass,
201	            options);
202	
203	    boolean isReleaseRaceFixEnabled =
204	        glideContext.getExperiments().isEnabled(EnableActiveResourceReleaseRaceFix.class);
205	
206	    EngineResource<?> memoryResource;
207	    synchronized (this) {
208	      memoryResource = loadFromMemory(key, isMemoryCacheable, isReleaseRaceFixEnabled, startTime);
209	
210	      if (memoryResource == null) {
211	        return waitForExistingOrStartNewJob(
212	            glideContext,
213	            model,
214	            signature,
215	            width,
216	            height,
217	            resourceClass,
218	            transcodeClass,
219	            priority,
220	            diskCacheStrategy,
221	            transformations,
222	            isTransformationRequired,
223	            isScaleOnlyOrNoTransform,
224	            options,
225	            isMemoryCacheable,
226	            useUnlimitedSourceExecutorPool,
227	            useAnimationPool,
228	            onlyRetrieveFromCache,
229	            cb,
230	            callbackExecutor,
231	            key,
232	            startTime);
233	      }
234	    }
235	
236	    // Avoid calling back while holding the engine lock, doing so makes it easier for callers to
237	    // deadlock.
238	    cb.onResourceReady(
239	        memoryResource, DataSource.MEMORY_CACHE, /* isLoadedFromAlternateCacheKey= */ false);
240	    return null;
241	  }
