3	import androidx.annotation.NonNull;
4	import java.io.FilterInputStream;
5	import java.io.IOException;
6	import java.io.InputStream;
7	
8	/**
9	 * Prevents {@link InputStream InputStreams} from overflowing their buffer by reading data past
10	 * their read limit.
11	 */
12	public class MarkEnforcingInputStream extends FilterInputStream {
13	  private static final int UNSET = Integer.MIN_VALUE;
14	  private static final int END_OF_STREAM = -1;
15	
16	  private int availableBytes = UNSET;
17	
18	  public MarkEnforcingInputStream(@NonNull InputStream in) {
19	    super(in);
20	  }
21	
22	  @Override
23	  public synchronized void mark(int readLimit) {
24	    super.mark(readLimit);
25	    availableBytes = readLimit;
26	  }
27	
28	  @Override
29	  public int read() throws IOException {
30	    if (getBytesToRead(1) == END_OF_STREAM) {
31	      return END_OF_STREAM;
32	    }
33	
34	    int result = super.read();
35	    updateAvailableBytesAfterRead(1 /* bytesRead */);
36	    return result;
37	  }
38	
39	  @Override
40	  public int read(@NonNull byte[] buffer, int byteOffset, int byteCount) throws IOException {
41	    int toRead = (int) getBytesToRead(byteCount);
42	    if (toRead == END_OF_STREAM) {
43	      return END_OF_STREAM;
44	    }
45	
46	    int read = super.read(buffer, byteOffset, toRead);
47	    updateAvailableBytesAfterRead(read);
48	    return read;
49	  }
50	
51	  @Override
52	  public synchronized void reset() throws IOException {
53	    super.reset();
54	    availableBytes = UNSET;
55	  }
56	
57	  @Override
58	  public long skip(long byteCount) throws IOException {
59	    long toSkip = getBytesToRead(byteCount);
60	    if (toSkip == END_OF_STREAM) {
61	      return 0;
62	    }
63	
64	    long read = super.skip(toSkip);
65	    updateAvailableBytesAfterRead(read);
66	    return read;
67	  }
68	
69	  @Override
70	  public int available() throws IOException {
71	    return availableBytes == UNSET
72	        ? super.available()
73	        : Math.min(availableBytes, super.available());
74	  }
75	
76	  private long getBytesToRead(long targetByteCount) {
77	    if (availableBytes == 0) {
78	      return END_OF_STREAM;
79	    } else if (availableBytes != UNSET && targetByteCount > availableBytes) {
80	      return availableBytes;
81	    } else {
82	      return targetByteCount;
83	    }
84	  }
85	
86	  private void updateAvailableBytesAfterRead(long bytesRead) {
87	    if (availableBytes != UNSET && bytesRead != END_OF_STREAM) {
88	      // See https://errorprone.info/bugpattern/NarrowingCompoundAssignment.
89	      availableBytes = (int) (availableBytes - bytesRead);
90	    }
91	  }
92	}
