  private static final String TAG = "FactoryPools";
  private static final int DEFAULT_POOL_SIZE = 20;
  private static final Resetter<Object> EMPTY_RESETTER =
      new Resetter<Object>() {
        @Override
        public void reset(@NonNull Object object) {
          // Do nothing.
        }
      };

  private FactoryPools() {}

  /**
