    return build(
        new SynchronizedPool<List<T>>(size),
        new Factory<List<T>>() {
          @NonNull
          @Override
          public List<T> create() {
            return new ArrayList<>();
          }
        },
        new Resetter<List<T>>() {
          @Override
          public void reset(@NonNull List<T> object) {
